using UnityEngine;
using UnityEditor;
using System.Collections.Generic;
using System.IO;
using UnityEngine.Rendering;
public class RoadsideGenerator : EditorWindow {
 int seed=42, leaves=16000, tex=1024; string folder; System.Random rng; Material bark,leaf,metal,wood; 
 [MenuItem("Tools/OSM/Roadside Tree Assets")] static void Open(){GetWindow<RoadsideGenerator>("Roadside Assets");}
 void OnGUI(){seed=EditorGUILayout.IntField("Seed",seed);leaves=EditorGUILayout.IntSlider("LOD0 individual leaves",leaves,1000,30000);tex=EditorGUILayout.IntPopup("Texture size",tex,new[]{"512","1024","2048"},new[]{512,1024,2048});if(GUILayout.Button("Generate separate prefabs"))Generate();}
 float R(float a,float b){return Mathf.Lerp(a,b,(float)rng.NextDouble());}
 Vector3 Unit(){float y=R(-1,1),a=R(0,6.283185f),r=Mathf.Sqrt(1-y*y);return new Vector3(r*Mathf.Cos(a),y,r*Mathf.Sin(a));}
 class Geo {public List<Vector3> v=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<int> t=new List<int>();public void Tri(int a,int b,int c){t.Add(a);t.Add(b);t.Add(c);} public int Add(Vector3 p,Vector2 u){v.Add(p);uv.Add(u);return v.Count-1;}}
 void Tube(Geo g,Vector3 a,Vector3 b,float ra,float rb,int sides,int rings,float bend){Vector3 d=(b-a).normalized;Vector3 x=Vector3.Cross(d,Mathf.Abs(d.y)>.9f?Vector3.right:Vector3.up).normalized;Vector3 z=Vector3.Cross(d,x);int k=g.v.Count;for(int j=0;j<=rings;j++){float f=j/(float)rings;Vector3 p=Vector3.Lerp(a,b,f)+x*Mathf.Sin(f*Mathf.PI)*bend;for(int i=0;i<=sides;i++){float u=i/(float)sides,ang=u*Mathf.PI*2;float radius=Mathf.Lerp(ra,rb,f)*(1+.10f*Mathf.Sin(ang*5+f*4)+.05f*Mathf.Cos(ang*9));g.Add(p+(x*Mathf.Cos(ang)+z*Mathf.Sin(ang))*radius,new Vector2(u*2,f*Vector3.Distance(a,b)));}}for(int j=0;j<rings;j++)for(int i=0;i<sides;i++){int q=k+j*(sides+1)+i;g.Tri(q,q+1,q+sides+1);g.Tri(q+1,q+sides+2,q+sides+1);} }
 void Leaf(Geo g,Vector3 p,float size){Vector3 d=Unit(),x=Vector3.Cross(d,Unit()).normalized;if(x.sqrMagnitude<.1f)x=Vector3.Cross(d,Vector3.up).normalized;Vector3 n=Vector3.Cross(x,d);int k=g.v.Count;for(int j=0;j<=4;j++){float f=j/4f,w=Mathf.Sin(f*Mathf.PI)*size*.33f;Vector3 c=p+d*size*f+n*Mathf.Sin(f*Mathf.PI)*size*.12f;g.Add(c-x*w,new Vector2(0,f));g.Add(c+n*w*.22f,new Vector2(.5f,f));g.Add(c+x*w,new Vector2(1,f));}for(int j=0;j<4;j++)for(int i=0;i<2;i++){int q=k+j*3+i;g.Tri(q,q+3,q+1);g.Tri(q+1,q+3,q+4);}}
 MeshRenderer SaveGeo(Geo g,Transform parent,string name,Material m){Mesh mesh=new Mesh{name=name,indexFormat=IndexFormat.UInt32};mesh.SetVertices(g.v);mesh.SetUVs(0,g.uv);mesh.SetTriangles(g.t,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,folder+"/"+name+".asset");var o=new GameObject(name);o.transform.SetParent(parent,false);o.AddComponent<MeshFilter>().sharedMesh=mesh;var r=o.AddComponent<MeshRenderer>();r.sharedMaterial=m;return r;}
 Texture2D Map(string name,Color[] pixels,bool linear,bool normal=false){var t=new Texture2D(tex,tex,TextureFormat.RGBA32,false,linear);t.SetPixels(pixels);t.Apply();string path=folder+"/"+name+".png";File.WriteAllBytes(path,t.EncodeToPNG());DestroyImmediate(t);AssetDatabase.ImportAsset(path);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.sRGBTexture=!linear;imp.wrapMode=TextureWrapMode.Repeat;imp.maxTextureSize=tex;if(normal)imp.textureType=TextureImporterType.NormalMap;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 Material Surface(string name,Color baseColor,int type){int n=tex*tex;var h=new float[n];var a=new Color[n];var norm=new Color[n];var rough=new Color[n];var ao=new Color[n];var pack=new Color[n];var height=new Color[n];for(int y=0;y<tex;y++)for(int x=0;x<tex;x++){float u=x/(float)tex,v=y/(float)tex;float noise=Mathf.PerlinNoise(u*32,v*32);float f=type==0? .5f+.35f*Mathf.Sin(u*150+Mathf.PerlinNoise(u*12,v*5)*6)+noise*.15f:type==1?.55f+.2f*Mathf.Sin((u-.5f)*45+Mathf.Abs(v-.5f)*55)+noise*.2f:noise;h[y*tex+x]=Mathf.Clamp01(f);}for(int y=0;y<tex;y++)for(int x=0;x<tex;x++){int i=y*tex+x;float f=h[i],r=type==1?.48f:type==2?.6f:.86f;float oc=Mathf.Lerp(.58f,1,f);a[i]=baseColor*Mathf.Lerp(.55f,1.35f,f);a[i].a=1;rough[i]=new Color(r,r,r,1);ao[i]=new Color(oc,oc,oc,1);height[i]=new Color(f,f,f,1);pack[i]=new Color(type==2?.45f:0,0,0,1-r);Vector3 nn=new Vector3((h[y*tex+(x+tex-1)%tex]-h[y*tex+(x+1)%tex])*3,(h[((y+tex-1)%tex)*tex+x]-h[((y+1)%tex)*tex+x])*3,1).normalized;norm[i]=new Color(nn.x*.5f+.5f,nn.y*.5f+.5f,nn.z*.5f+.5f,1);}var sh=Shader.Find("Universal Render Pipeline/Lit");if(!sh)sh=Shader.Find("Standard");var m=new Material(sh);var al=Map(name+"_Albedo",a,false);var nm=Map(name+"_Normal",norm,true,true);var pk=Map(name+"_MetallicSmoothness",pack,true);var ocmap=Map(name+"_AO",ao,true);Map(name+"_Roughness",rough,true);Map(name+"_Height",height,true);m.SetTexture(m.HasProperty("_BaseMap")?"_BaseMap":"_MainTex",al);m.SetTexture("_BumpMap",nm);m.SetTexture("_MetallicGlossMap",pk);m.SetTexture("_OcclusionMap",ocmap);m.SetFloat("_Smoothness",1);m.SetFloat("_GlossMapScale",1);m.EnableKeyword("_NORMALMAP");m.EnableKeyword("_METALLICSPECGLOSSMAP");m.EnableKeyword("_METALLICGLOSSMAP");m.EnableKeyword("_OCCLUSIONMAP");if(type==1&&m.HasProperty("_Cull"))m.SetFloat("_Cull",0);m.enableInstancing=true;AssetDatabase.CreateAsset(m,folder+"/"+name+".mat");return m;}
 void Tree(){var root=new GameObject("RoadsideTree");var lods=new LOD[3];for(int l=0;l<3;l++){rng=new System.Random(seed);var b=new Geo();var f=new Geo();int sides=24>>l;Tube(b,Vector3.zero,new Vector3(.25f,4.5f,0),.43f,.16f,sides,24>>l,.15f);var tips=new List<Vector3>();for(int i=0;i<12;i++){float ang=i*2.39996f;Vector3 radial=new Vector3(Mathf.Cos(ang),0,Mathf.Sin(ang));Vector3 start=new Vector3(.1f,2.3f+i*.19f,0);Vector3 end=start+radial*R(1.6f,3.4f)+Vector3.up*R(1.8f,3.3f);Tube(b,start,end,.13f,.035f,sides,12>>l,.23f);for(int j=0;j<6;j++){Vector3 s=Vector3.Lerp(start,end,.35f+j*.12f);Vector3 e=s+radial*R(.3f,1.1f)+Unit()*.8f+Vector3.up*R(.4f,1.3f);Tube(b,s,e,.04f,.008f,Mathf.Max(4,sides/2),Mathf.Max(2,8>>l),.09f);tips.Add(e);}}for(int i=0;i<10;i++){float ang=i*.6283f;Vector3 d=new Vector3(Mathf.Cos(ang),0,Mathf.Sin(ang));Tube(b,Vector3.up*.25f,d*R(1.3f,2.5f)-Vector3.up*.3f,.17f,.018f,sides,12>>l,.15f);for(int j=0;j<3;j++)Tube(b,d*(.6f+j*.35f),d*(1.5f+j*.4f)+new Vector3(-d.z,-.45f,d.x)*R(-.8f,.8f),.045f,.004f,Mathf.Max(4,sides/2),4,.1f);}int count=leaves/(l==0?1:l==1?4:12);for(int i=0;i<count;i++)Leaf(f,tips[i%tips.Count]+Unit()*R(.05f,.85f),R(.13f,.29f));var br=SaveGeo(b,root.transform,"TreeWood_LOD"+l,bark);var fr=SaveGeo(f,root.transform,"TreeLeaves_LOD"+l,leaf);lods[l]=new LOD(l==0?.42f:l==1?.16f:.025f,new Renderer[]{br,fr});Debug.Log("Tree LOD"+l+" triangles: "+(b.t.Count+f.t.Count)/3);}var group=root.AddComponent<LODGroup>();group.SetLODs(lods);group.RecalculateBounds();var col=root.AddComponent<CapsuleCollider>();col.center=Vector3.up*2;col.height=4;col.radius=.4f;root.AddComponent<RoadsideBreakable>();PrefabUtility.SaveAsPrefabAsset(root,folder+"/RoadsideTree.prefab");DestroyImmediate(root);}
 void Cube(Transform p,string name,Vector3 pos,Vector3 scale,Material m){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name=name;o.transform.SetParent(p,false);o.transform.localPosition=pos;o.transform.localScale=scale;o.GetComponent<Renderer>().sharedMaterial=m;}
 void Cabinet(){var o=new GameObject("UtilityCabinet");Cube(o.transform,"Back",new Vector3(0,.9f,.19f),new Vector3(.6f,1.8f,.04f),metal);foreach(int s in new[]{-1,1})Cube(o.transform,"Side",new Vector3(s*.28f,.9f,0),new Vector3(.04f,1.8f,.4f),metal);foreach(float y in new[]{.02f,1.78f})Cube(o.transform,"Cap",new Vector3(0,y,0),new Vector3(.6f,.04f,.4f),metal);Cube(o.transform,"Internal panel",new Vector3(0,1.1f,.1f),new Vector3(.42f,.6f,.09f),wood);var pivot=new GameObject("DoorHinge");pivot.transform.SetParent(o.transform,false);pivot.transform.localPosition=new Vector3(-.3f,.9f,-.22f);Cube(pivot.transform,"Door",new Vector3(.3f,0,0),new Vector3(.6f,1.8f,.04f),metal);Cube(pivot.transform,"Handle",new Vector3(.52f,0,-.04f),new Vector3(.035f,.16f,.06f),wood);pivot.AddComponent<RoadsideDoor>();PrefabUtility.SaveAsPrefabAsset(o,folder+"/UtilityCabinet.prefab");DestroyImmediate(o);}
 void Hedge(){var o=new GameObject("Hedge");var b=new Geo();var f=new Geo();for(int j=0;j<30;j++){Vector3 p=new Vector3(R(-.9f,.9f),0,R(-.25f,.25f));Vector3 e=p+new Vector3(R(-.2f,.2f),R(.45f,.85f),R(-.2f,.2f));Tube(b,p,e,.018f,.004f,6,5,.05f);for(int i=0;i<100;i++)Leaf(f,e+Unit()*R(.02f,.3f),R(.06f,.13f));}SaveGeo(b,o.transform,"HedgeWood",bark);SaveGeo(f,o.transform,"HedgeLeaves",leaf);PrefabUtility.SaveAsPrefabAsset(o,folder+"/Hedge.prefab");DestroyImmediate(o);}
 void Generate(){folder="Assets/RoadsideTree/Generated_"+System.DateTime.Now.ToString("yyyyMMdd_HHmmss_fff");AssetDatabase.CreateFolder("Assets/RoadsideTree",Path.GetFileName(folder));rng=new System.Random(seed);try{bark=Surface("Bark",new Color(.38f,.27f,.17f),0);leaf=Surface("Leaf",new Color(.26f,.48f,.08f),1);metal=Surface("Cabinet",new Color(.65f,.65f,.62f),2);wood=Surface("Interior",new Color(.25f,.25f,.22f),3);Tree();Hedge();Cabinet();AssetDatabase.SaveAssets();}finally{EditorUtility.ClearProgressBar();}Debug.Log("Generated assets: "+folder);}
}
